(() => {
 const live=document.querySelector('#live-media'),replays=document.querySelector('#replay-media');if(!live||!replays)return;
 const lang=document.documentElement.lang==='en'?'en':'fr',api='https://twjpjzalyvbsdpbzhqln.supabase.co/functions/v1/public-event';
 const empty=lang==='fr'?'Aucun lien publié pour le moment.':'No link published yet.';
 const card=item=>{const article=document.createElement('article');article.className='media-card';const type=document.createElement('span');type.className='meta';type.textContent=item.media_type==='live'?'LIVE':'REPLAY';const title=document.createElement('h3');title.textContent=item['title_'+lang]||item.title_fr;const link=document.createElement('a');link.className='action';link.href=item.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent=(item.media_type==='live'?(lang==='fr'?'Voir le direct':'Watch live'):(lang==='fr'?'Voir sur YouTube':'Watch on YouTube'))+' ↗';article.append(type,title,link);return article;};
 (window.ATX_PUBLIC_EVENTS?window.ATX_PUBLIC_EVENTS():fetch(api,{signal:AbortSignal.timeout(12000)}).then(response=>{if(!response.ok)throw Error();return response.json();})).then(data=>{const items=data.media||[],streams=items.filter(x=>x.media_type==='live'),videos=items.filter(x=>x.media_type==='replay');live.replaceChildren(streams[0]?card(streams[0]):Object.assign(document.createElement('p'),{textContent:empty}));replays.replaceChildren(...(videos.length?videos.map(card):[Object.assign(document.createElement('p'),{textContent:empty})]));}).catch(()=>{live.textContent=replays.textContent=lang==='fr'?'Médias momentanément indisponibles.':'Media temporarily unavailable.';});
})();
